flowchart TB
  P1@{ svc: "Amazon EC2 Auto Scaling", label: "第 1 部<br/>指標で伸ばす<br/>EC2 Auto Scaling" }
  P2@{ svc: "Amazon ECS", label: "第 2 部<br/>コンテナ<br/>ECS・Fargate・EKS" }
  P3@{ svc: "AWS Lambda", label: "第 3 部<br/>サーバーレス<br/>Lambda・SQS<br/>API Gateway" }
  P4@{ svc: "Elastic Load Balancing", label: "第 4 部<br/>負荷分散とキャッシュ<br/>Elastic Load Balancing<br/>ElastiCache" }
  P5@{ svc: "Amazon Route 53", label: "第 5 部<br/>複数リージョン<br/>Route 53<br/>Global Accelerator" }
  P1 ~~~ P2
  P2 ~~~ P3
  P3 ~~~ P4
  P4 ~~~ P5

  T["条件から選ぶ表"]
  P5 ~~~ T

flowchart TB
  ECS@{ svc: "Amazon ECS", label: "ECS のサービス<br/>実際に動くタスク数" }
  CW@{ svc: "Amazon CloudWatch", label: "CloudWatch<br/>届くまで指標は無い" }
  SAS["Service Auto Scaling<br/>動くタスク数を起点に"]
  ECS -- "1 分ごとの指標" --> CW
  SAS -- "タスク数を増減" --> ECS

flowchart TB
  ECS@{ svc: "Amazon ECS", label: "ECS<br/>新しいタスク" }
  ASG@{ svc: "Amazon EC2 Auto Scaling", label: "Auto Scaling group<br/>targetCapacity" }
  I1@{ svc: "Amazon EC2", label: "インスタンス" }
  I2@{ svc: "Amazon EC2", label: "インスタンス" }
  N["既定の 100% では<br/>増やす間 PENDING"]
  ECS -- "台数を管理" --> ASG
  ASG --> I1
  ASG --> I2
  N -.- ECS

flowchart TB
  Q@{ svc: "Amazon SQS", label: "SQS のキュー<br/>メッセージ" }
  L@{ svc: "AWS Lambda", label: "Lambda 関数<br/>partial batch response" }
  N["一部が失敗しても<br/>成功分は再試行させない"]
  Q -- "バッチ" --> L
  L -.- N

flowchart TB
  C["クライアント"]
  LB@{ svc: "Elastic Load Balancing", label: "ロードバランサー<br/>健康を見る" }
  T1@{ svc: "Amazon EC2", label: "ターゲット<br/>例 EC2" }
  T2@{ svc: "Amazon EC2", label: "ターゲット<br/>例 EC2" }
  EC@{ svc: "Amazon ElastiCache", label: "ElastiCache<br/>キャッシュ" }
  DS["データストア"]
  C --> LB
  LB -- "健全な先だけ" --> T1
  LB --> T2
  T1 -- "1 まず聞く" --> EC
  T1 -- "2 無い・期限切れ" --> DS

flowchart TB
  P1@{ svc: "Amazon EC2 Auto Scaling", label: "第 1 部<br/>指標で伸ばす<br/>使用率の指標を目標に" }
  P2@{ svc: "Amazon ECS", label: "第 2 部<br/>コンテナ<br/>起点・空き・Spot・Pod" }
  P3@{ svc: "AWS Lambda", label: "第 3 部<br/>サーバーレス<br/>同時実行・一部の失敗<br/>429" }
  P4@{ svc: "Elastic Load Balancing", label: "第 4 部<br/>負荷分散とキャッシュ<br/>健全な先<br/>先にキャッシュ" }
  P5@{ svc: "Amazon Route 53", label: "第 5 部<br/>複数リージョン<br/>Route 53 latency<br/>Global Accelerator" }
